// ------------------------------------------------------------------ slots
function slotV2(f) {
  if (f <= 4) return { fixture: f, season: 1, pos: f, band: 'opening', r: 0, engine: 'A and B off' };
  const season = 2 + Math.floor((f - 5) / 8), pos = 1 + ((f - 5) % 8), r = Math.floor((season - 2) / 2);
  let band;
  if (pos === 8) band = 'closing';
  else if (season % 2 === 0) band = pos === 7 ? 'hard' : 'standard';
  else band = pos === 4 ? 'standard' : 'hard';
  return { fixture: f, season, pos, band, r, engine: f <= 8 ? 'B only' : 'A+B' };
}

