// ------------------------------------------------------------------ helpers
const yBandOf = G.yBandOf;
function metaOf(L, tplId) {
  const fin = L.att[L.order[L.order.length - 1]], side = fin.x < 23 ? 'left' : fin.x > 27 ? 'right' : 'centre';
  const ln = L.def.filter(d => d.t === 'line'), yL = ln.length ? ln.reduce((s, d) => s + d.y, 0) / ln.length : null;
  const t = BY_ID[tplId];
  return { template: tplId, side, yBand: yBandOf(yL), finisher: t.finisher, ending: t.ending };
}
function ctxFor(L, s, tplId, roles) {
  return { fixture: s.fixture, band: G.bandFor(s.band, s.r), tpl: Object.assign({}, BY_ID[tplId]), roles: roles || [], runner: L.order.length - 1, novice: s.fixture <= 20 };
}
function setEngine(L, f) { const e = K.expectedEngine(f); if (e) L.engine = e; else delete L.engine; }

// the clock for a hand-built level, fitted as generate.js step 7 fits a generated one: whole seconds inside the band's
// slack (up to 1 s over), bot / clock 0.80 or less, the difficulty estimate inside the owner's range for the band,
// nearest its target; the human model must clear 90% within 60 takes
function fitClock(L, route, s, tplId, roles) {
  const ctx = ctxFor(L, s, tplId, roles), band = ctx.band;
  L.time = 20;
  const D = K.dynamicChecks(L, route, ctx, {});
  const terms = DF.routeTerms(D), bot = D.bot, tries = [];
  for (let c = 7; c <= 14; c++) {
    const sl = c - bot; if (sl < band.slack[0] - 0.2 || sl > band.slack[1] + 1.0 || bot / c > 0.8) continue;
    L.time = c; const m = K.model(L), e = DF.estimate(m.median, terms, bot, c).takes;
    tries.push({ c, median: m.median, cleared: m.cleared, est: e, m });
  }
  const ok = tries.filter(t => t.cleared >= 0.9 && t.est >= band.ownerR[0] && t.est <= band.ownerR[1]);
  const pick = (ok.length ? ok : tries).slice().sort((a, b) => Math.abs(a.est - band.ownerT) - Math.abs(b.est - band.ownerT))[0];
  L.time = pick ? pick.c : 12;
  return { D, terms, tries: tries.map(t => ({ c: t.c, median: t.median, cleared: t.cleared, est: t.est })), pick: pick ? { c: pick.c, est: pick.est, median: pick.median } : null, inBand: !!ok.length, model: pick && pick.m };
}

// ------------------------------------------------------------------ commands
const args = process.argv.slice(2), cmd = args[0];
const opt = (k, d) => { const i = args.indexOf('--' + k); return i >= 0 ? args[i + 1] : d; };
const SEED = +opt('seed', 2611);

if (cmd === 'plan') {
  for (let f = 1; f <= 60; f++) { const s = slotV2(f); console.log(f, 'season', s.season, 'pos', s.pos, s.band, 'r' + s.r, s.engine, f <= 4 ? 'kept' : PLAN[f]); }
}

if (cmd === 'gen') {
  const from = +opt('from', 5), to = +opt('to', 60), out = opt('out'), maxAttempts = +opt('attempts', 40), results = {};
  const stats = {};
  let prev = null;
  if (from > 5) { const p = PLAN[from - 1]; if (typeof p === 'string') prev = metaOf(FAVS[p.slice(4)].level, FAVS[p.slice(4)].tpl); }
  if (opt('prev')) { const r = JSON.parse(fs.readFileSync(opt('prev'), 'utf8')).results[from - 1]; if (r && r.meta) prev = { template: r.meta.template, side: r.meta.side, yBand: r.meta.yBand, finisher: r.meta.finisher, ending: r.meta.ending }; }
  for (let f = from; f <= to; f++) {
    const s = slotV2(f), p = opt('tpl') ? opt('tpl').split(',') : PLAN[f];
    if (typeof p === 'string') { prev = metaOf(FAVS[p.slice(4)].level, FAVS[p.slice(4)].tpl); continue; }
    const next = PLAN[f + 1], nextFav = typeof next === 'string' ? metaOf(FAVS[next.slice(4)].level, FAVS[next.slice(4)].tpl) : null;
    const avoid = {};
    if (prev) { avoid.side = prev.side; if (prev.yBand !== 'none') avoid.yBand = prev.yBand; if (prev.ending === 'cutback') avoid.noCutback = true; avoid.finishers = [prev.finisher]; }
    else if (nextFav) avoid.side = nextFav.side;
    let res = null;
    for (const tpl of p) {
      process.stderr.write(`fixture ${f} (${s.band}, repeat ${s.r}) ${tpl} ... `);
      const t0 = Date.now();
      res = G.generate({ seed: hashSeed(SEED, 'v2', f, tpl), band: s.band, bandId: s.band, fixture: f, season: s.r, template: tpl, avoid, stats, novice: f <= 20, maxAttempts });
      process.stderr.write(res.ok ? `ok, ${res.meta.attempts} attempts, ${((Date.now() - t0) / 1000).toFixed(0)} s, clock ${res.level.time}, estimate ${res.meta.estimate}\n` : `no level (${((Date.now() - t0) / 1000).toFixed(0)} s)\n`);
      if (res.ok) break;
    }
    if (res && res.ok) {
      results[f] = { slot: s, meta: res.meta, checks: res.checks, level: res.level, script: res.script };
      prev = { template: res.meta.template, side: res.meta.side, yBand: res.meta.yBand, finisher: res.meta.finisher, ending: res.meta.ending };
    } else { results[f] = { slot: s, failed: true }; prev = null; }
    if (out) fs.writeFileSync(out, JSON.stringify({ seed: SEED, stats, results }));
  }
}

if (cmd === 'favs') {
  const out = opt('out'), only = opt('only'), results = {};
  for (const k of Object.keys(FAVS)) {
    if (only && !only.split(',').includes(k)) continue;
    const fv = FAVS[k], s = slotV2(fv.fixture), L = clone(fv.level);
    setEngine(L, s.fixture);
    // the defence's speed into the slot's band (rulebook 7.2, dial 2 of 7.1): the whole defence moves by the same step,
    // so the line stays one speed and markers and hunters stay within 0.3 of it; then the clock (dial 1) is fitted.
    // If the estimate is still below the band at the shortest clock, one or two more steps of 0.1 inside the band.
    const band = G.bandFor(s.band, s.r), spd0 = L.def.map(d => d.spd === undefined ? 5.2 : d.spd);
    const lineS = spd0[L.def.findIndex(d => d.t === 'line')];
    const base = lineS < band.spd[0] ? +(band.spd[0] - lineS).toFixed(1) : lineS > band.spd[1] ? +(band.spd[1] - lineS).toFixed(1) : 0;
    const { synth, polish } = require('./route.js');
    let route, fit, S, ctx, shift, best = null;
    // into the band first, then a step or two quicker if the estimate is low; if the route stops meeting the dynamic
    // checks at that speed (the faster defence closes a window to a needle), back towards the speed he rated it at
    const steps = [0, 0.1, 0.2, -0.1, -0.2, -0.3].map(e => +(base + e).toFixed(1)).filter((v, i, a) => a.indexOf(v) === i && (base >= 0 ? v >= 0 : v <= 0) && lineS + v <= 5.7 + 1e-9);
    if (!steps.includes(0)) steps.push(0);
    for (const sh of steps) {
      shift = sh;
      L.def.forEach((d, i) => { d.spd = Math.min(5.7, +(spd0[i] + shift).toFixed(1)); });
      route = fv.route && !fv.resynth ? clone(fv.route) : null;
      L.time = 20;
      if (!route || !lab.solve(L, route).ok) {
        const R = synth(L, BY_ID[fv.tpl].build(fv.params).plan, { maxSims: 4000, solutions: 4 });
        if (!R.ok) { route = null; console.log(k, 'no route at speed shift', shift); continue; }
        route = R.route.scripts.map(x => clone(x)); const pol = polish(L, route); if (lab.solve(L, pol).ok) route = pol;
      }
      ctx = ctxFor(L, s, fv.tpl, fv.roles);
      S = K.staticChecks(L, ctx);
      fit = fitClock(L, route, s, fv.tpl, fv.roles);
      if (fit.D.fails.length) { console.log(k, 'dynamic fails at speed shift', shift, fit.D.fails.join('; ')); continue; }
      best = { shift, route, fit, S, ctx, def: clone(L.def), time: L.time };
      if (fit.inBand) break;
    }
    if (!best) { console.log(k, 'no speed meets the dynamic checks'); continue; }
    ({ shift, route, fit, S, ctx } = best); L.def = best.def; L.time = best.time;
    const Fn = K.finalChecks(L, route, Object.assign({ modelCache: fit.model, terms: fit.terms }, ctx), hashSeed(SEED, 'jitter', k));
    const r = { key: k, slot: s, source: fv.source, changes: fv.changes, level: L, script: route, meta: Object.assign(metaOf(L, fv.tpl), { templateName: BY_ID[fv.tpl].name, fav: k, estimate: fit.pick && fit.pick.est }),
      speedShift: shift, checks: { static: S, dynamic: Object.assign({}, fit.D, { W: undefined }), final: Object.assign({}, Fn, { A6: Object.assign({}, Fn.A6) }) }, clock: { tries: fit.tries, pick: fit.pick, inBand: fit.inBand } };
    results[k] = r;
    console.log(k, 'fixture', s.fixture, s.band, 'static', S.fails.join('; ') || 'pass', '| dynamic', fit.D.fails.join('; ') || 'pass', '| clock', L.time, 'est', fit.pick && fit.pick.est, fit.inBand ? 'in band' : 'OUT OF BAND', JSON.stringify(fit.tries),
      '| final', Fn.fails.join('; ') || 'pass', 'jitter', (Fn.A3 || []).join('/'));
    if (out) fs.writeFileSync(out, JSON.stringify(results));
  }
}

// ------------------------------------------------------------------ write the live packs
// Fixture names: short football phrases, unique, matching the move (the story line in story.js matches them too).
// Permanent ids: c01-c60 as first issued here. An id is never renumbered or reused: a level added later takes c61 on.
// oldName: the name the level had in the first campaign, for the save migration in game.js, only where the same move
// on the same pitch carried over (the opening four, Five-man move, Beat the trap).
const NAMES = {
  5: 'The third man',
  6: 'Draw him out',
  7: 'Along the line',
  8: 'Come short, go long',
  9: 'The dropping nine',
  10: 'Past the hunters',
  11: 'Five in a row',
  12: 'Nothing over the top',
  13: 'Into the hole',
  14: 'Run at him',
  15: 'The blind side',
  16: 'Short, not long',
  17: 'Past the press',
  18: 'Make him step out',
  19: 'Up, off and in',
  20: 'All the way through',
  21: 'Switch of play',
  22: 'Pull it back',
  23: 'Bend round them',
  24: 'Beat the press',
  25: 'Empty the middle',
  26: 'Check and spin',
  27: 'Catch them upfield',
  28: 'Every man touches it',
  29: 'Round the back',
  30: 'Hit the far man',
  31: 'Ball inside the full-back',
  32: 'Under the sweeper',
  33: 'Beat the trap',
  34: 'Bounce it off the 9',
  35: 'The run from wide',
  36: 'Bend the run',
  37: 'Change the point',
  38: 'Out from the back',
  39: 'Bend in behind',
  40: 'Pull the centre-half',
  41: 'Back, then in behind',
  42: 'Spin in behind',
  43: 'Two at the back',
  44: 'The seam',
  45: 'Take on the line',
  46: 'The cut-back',
  47: 'Third-man run',
  48: 'Keeper off his line',
  49: 'Run the line',
  50: 'Lay it back, then in',
  51: 'Over to the far side',
  52: 'Through the high line',
  53: 'Through the first line',
  54: 'Off the 9',
  55: 'Dart inside',
  56: 'Curve it in behind',
  57: 'The double movement',
  58: 'Commit the centre-half',
  59: 'Break at speed',
  60: 'Five-man move'
};
const OLDNAME = { trap: 'Beat the trap', five: 'Five-man move' };
const lit = v => {
  if (Array.isArray(v)) return '[' + v.map(lit).join(', ') + ']';
  if (v && typeof v === 'object') return '{ ' + Object.keys(v).map(k => (/^[a-z_]\w*$/i.test(k) ? k : JSON.stringify(k)) + ': ' + lit(v[k])).join(', ') + ' }';
  return typeof v === 'string' ? "'" + v.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'" : String(v);
};
function levelText(L, note) {
  const keys = Object.keys(L).filter(k => !['att', 'def', 'order'].includes(k));
  const head = ['id', 'oldName', 'name', 'time', 'engine', 'brief', 'gk', 'lines'].filter(k => L[k] !== undefined);
  const rest = keys.filter(k => !head.includes(k));
  const o = [];
  o.push('    // ' + note);
  o.push('    {');
  head.concat(rest).forEach(k => o.push('      ' + k + ': ' + lit(L[k]) + ','));
  o.push('      att: [\n' + L.att.map(a => '        ' + lit(a)).join(',\n') + '\n      ],');
  o.push('      order: ' + lit(L.order) + ',');
  o.push('      def: [\n' + L.def.map(d => '        ' + lit(d)).join(',\n') + '\n      ]');
  o.push('    }');
  return o.join('\n');
}
if (cmd === 'write') {
  const files = args.slice(1).filter(a => !a.startsWith('--'));
  const gen = {}, fav = {};
  files.forEach(f => { const j = JSON.parse(fs.readFileSync(f, 'utf8')); if (j.results) Object.assign(gen, j.results); else Object.values(j).forEach(r => { fav[r.slot.fixture] = r; }); });
  const levels = [], scripts = [], notes = [];
  for (let f = 5; f <= 60; f++) {
    const p = PLAN[f], isFav = typeof p === 'string';
    const r = isFav ? fav[f] : gen[f];
    if (!r || r.failed) throw new Error('no level for fixture ' + f);
    const L = clone(r.level);
    const out = { id: 'c' + String(f).padStart(2, '0') };
    if (isFav && OLDNAME[p.slice(4)]) out.oldName = OLDNAME[p.slice(4)];
    Object.assign(out, L);
    if (NAMES[f]) out.name = NAMES[f];
    levels.push(out); scripts.push(r.script);
    notes.push(isFav ? `${f}: ${r.meta.templateName}, hand-built favourite (${r.source}), ${r.slot.band}` : `${f}: ${r.meta.templateName}, generated (seed ${r.meta.seed}, attempt ${r.meta.attempt}), ${r.slot.band}`);
  }
  for (let pk = 2; pk <= 8; pk++) {
    const a = (pk - 2) * 8, lv = levels.slice(a, a + 8), sc = scripts.slice(a, a + 8), nt = notes.slice(a, a + 8);
    const f0 = 5 + a, f1 = f0 + 7;
    const head = `/* Pack ${pk}: season ${pk} of the story, fixtures ${f0}-${f1}. Campaign version 2 (docs/foundation/21-campaign-v2.md),\n` +
      `   built by tools/gen/campaign-v2.js to RULEBOOK.md version 2: generated levels and the owner's favourite hand-built ones.\n` +
      `   Rebuild rather than edit by hand; ids (c01-c60) are permanent and never reused. */\n`;
    const body = '(function (root) {\n  const L = (root.OMT_LEVELS = root.OMT_LEVELS || []);\n  L.push(\n' + lv.map((L, i) => levelText(L, nt[i])).join(',\n') + '\n  );\n})(typeof module !== \'undefined\' ? global : window);\n';
    fs.writeFileSync(path.join(REPO, 'one-man-team', 'js', 'levels', 'pack' + pk + '.js'), head + body);
    fs.writeFileSync(path.join(REPO, 'tools', 'scripts', 'pack' + pk + '.js'), `// Bot solutions for pack ${pk}, one array per level, one entry per round (written by tools/gen/campaign-v2.js).\nmodule.exports = [\n` +
      sc.map((s, i) => `  // ${lv[i].name} (fixture ${f0 + i})\n  [\n` + s.map(x => '    ' + lit(x)).join(',\n') + '\n  ]').join(',\n') + '\n];\n');
  }
  console.log('wrote packs 2-8 and tools/scripts/pack2-8.js');
}

module.exports = { slotV2, PLAN, FAVS, metaOf, fitClock, NAMES };
